const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const clipId = body.clip_id || ((body.job_id != null && body.clip_index != null) ? (body.job_id + ':' + body.clip_index) : null);
if (!clipId) throw new Error('LOOM_CARD_INVALID: missing clip_id');
return [{ json: {
  clip_id: clipId,
  preview_url: body.preview_url || body.asset_url || body.candidate_clip_url || null,
  source_url: body.source_url || body.source || null,
  suggested_hook: body.suggested_hook || body.hook || null,
  suggested_caption: body.suggested_caption || body.caption || null,
  overall_score: body.overall_score ?? null,
  decision: body.decision || null,
  duration_seconds: body.duration_seconds ?? body.clip_duration_seconds ?? null,
  tenant_id: body.tenant_id || null,
  run_id: body.run_id || null,
  job_id: body.job_id || null,
  recipe: body.recipe || null,
  version: body.version || body.schema_version || null
} }];

const c = $json;
const lines = [];
lines.push('🎬 **LOOM Candidate Review**');
lines.push('');
if (c.preview_url) lines.push('**Preview:** ' + c.preview_url);
if (c.source_url) lines.push('**Source:** ' + c.source_url);
if (c.suggested_hook) lines.push('**Hook:** ' + c.suggested_hook);
if (c.suggested_caption) lines.push('**Caption:** ' + c.suggested_caption);
if (c.overall_score !== null && c.overall_score !== undefined) lines.push('**LOOM Score:** ' + c.overall_score + (c.decision ? ' (' + c.decision + ')' : ''));
if (c.duration_seconds !== null && c.duration_seconds !== undefined) lines.push('**Duration:** ' + c.duration_seconds + 's');
if (c.tenant_id) lines.push('**Tenant:** ' + c.tenant_id);
if (c.run_id) lines.push('**Run ID:** ' + c.run_id);
if (c.clip_id) lines.push('**Clip ID:** ' + c.clip_id);

const scorePayload = {
  clip_id: c.clip_id,
  asset_url: c.preview_url,
  tenant_id: c.tenant_id,
  run_id: c.run_id,
  job_id: c.job_id,
  schema_version: (c.version && typeof c.version === 'string') ? c.version : null,
  overall_score: c.overall_score,
  decision: c.decision,
  suggested_hook: c.suggested_hook,
  suggested_caption: c.suggested_caption
};

return [{ json: { discord_text: lines.join('\n'), score_payload: scorePayload, preview_url: c.preview_url } }];

const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const clipId = body.clip_id;
if (!clipId) throw new Error('LOOM_REVIEW_INVALID: missing clip_id');

const validDecisions = ['approve', 'reject', 'hold'];
const rawDecision = body.decision;
if (!validDecisions.includes(rawDecision)) {
  throw new Error('LOOM_REVIEW_INVALID: decision must be approve|reject|hold, got ' + JSON.stringify(rawDecision));
}

let decision = rawDecision;
let finalStatus = null;
let reviewerInstructions = body.reviewer_instructions || null;
let rejectionCategory = body.rejection_category || null;

if (rawDecision === 'reject' && !rejectionCategory) {
  throw new Error('LOOM_REVIEW_INVALID: rejection_category is required for reject');
}

if (body.action === 'retry_failed_step') {
  decision = 'hold';
  finalStatus = 'retry_requested';
  reviewerInstructions = (reviewerInstructions ? reviewerInstructions + '; ' : '') + 'retry smallest failed operation once, then hold';
}

if (!finalStatus) {
  finalStatus = decision === 'approve' ? 'approved' : (decision === 'reject' ? 'rejected' : 'on_hold');
}

const reviewPayload = {
  clip_id: clipId,
  asset_url: body.asset_url || body.preview_url || null,
  tenant_id: body.tenant_id || null,
  reviewer: body.reviewer || 'bryan',
  decision: decision,
  rejection_category: (decision === 'reject') ? rejectionCategory : null,
  reviewer_instructions: reviewerInstructions,
  final_status: finalStatus
};

return [{ json: { review_payload: reviewPayload, publication_enabled: false } }];

const persisted = $json;
const hasError = !!persisted.error;
return [{ json: {
  persisted: !hasError,
  clip_id: persisted.clip_id || ($('Validate Review Decision').item.json.review_payload && $('Validate Review Decision').item.json.review_payload.clip_id) || null,
  decision: (persisted.decision) || ($('Validate Review Decision').item.json.review_payload && $('Validate Review Decision').item.json.review_payload.decision) || null,
  final_status: persisted.final_status || null,
  publication_enabled: false,
  note: 'Durable decision saved. Publication is NOT triggered by this workflow.'
} }];
